// Parse module structure from collected data
const findOutput = $('Find All Source Files').first().json.stdout;
const metaOutput = $('Collect Build Metadata').first().json.stdout;

const files = findOutput.split('\n').filter(Boolean);
const metaLines = metaOutput.split('\n').filter(Boolean);

const commitHash = metaLines[0]?.trim() || 'unknown';
const versionLine = metaLines[4]?.trim() || 'version = "0.0.0"';
const version = (versionLine.match(/"([^"]+)"/) || [])[1] || '0.0.0';
const lineCountLine = metaLines[6]?.trim() || '0 total';

const manifest = {
  name: 'MiastoX', version: version, commit: commitHash,
  buildDate: new Date().toISOString(),
  totalFiles: files.length, totalLines: parseInt(lineCountLine) || 0,
  modules: files.map(f => {
    const relPath = f.replace('src/', '');
    const category = relPath.split('/')[0];
    return { path: relPath, category, name: relPath.split('/').pop().replace('.luau','').replace('.lua','') };
  })
};

const categories = {};
manifest.modules.forEach(m => { if (!categories[m.category]) categories[m.category] = []; categories[m.category].push(m.name); });

return [{ json: { manifest, categories, version, commit: commitHash, artifactName: `MiastoX-artifacts-v${version}-${commitHash.substring(0,7)}.json` } }];

return [{
  json: {
    status: 'generated',
    artifacts: [
      'artifacts/manifest.json',
      'artifacts/src-bundle.zip',
      'artifacts/docs/README.md',
      'artifacts/build-info.json'
    ],
    version: $input.first().json.version,
    commit: $input.first().json.commit,
    path: '/Development/repos/MiastoX/artifacts/',
    timestamp: new Date().toISOString()
  }
}];
